updateUI();
function tileDraw(x,y,t,sx,sy){const px=sx*TILE,py=sy*TILE;let v=rand(x,y),g=['#82b978','#7db474','#86be7b','#7bb170'][Math.floor(v*4)];ctx.fillStyle=t===T.WATER?'#76b5bd':t===T.PATH?'#d8bd88':t===T.BRIDGE?'#c79c68':t===T.TREE?'#4c7957':t===T.FLOWER?'#83b879':t===T.TALL?'#72a969':t===T.ROCK?'#929c84':g;ctx.fillRect(px,py,TILE+1,TILE+1);
if(t===T.GRASS||t===T.FLOWER){ctx.fillStyle='#477c4a24';ctx.fillRect(px+(x%5)*5,py+(y%4)*6,2,3);if(t===T.FLOWER){ctx.fillStyle=['#fff4ce','#eab5aa','#e8d88c'][Math.floor(rand(x+2,y+5)*3)];ctx.fillRect(px+8+Math.floor(v*13),py+9+Math.floor(rand(y,x)*12),3,3)}}
if(t===T.TALL){ctx.fillStyle='#487a4e';for(let i=0;i<4;i++){let ox=4+i*7,wiggle=Math.sin(performance.now()/550+x*3+i)*1.5;ctx.beginPath();ctx.moveTo(px+ox,py+27);ctx.quadraticCurveTo(px+ox-3+wiggle,py+15,px+ox+1,py+7+rand(x+i,y)*8);ctx.quadraticCurveTo(px+ox+6,py+16,px+ox+4,py+27);ctx.fill()}}
if(t===T.WATER){ctx.strokeStyle='#c2e0d079';ctx.lineWidth=1;let yy=py+8+Math.floor(v*14);ctx.beginPath();ctx.moveTo(px+5,yy);ctx.lineTo(px+14,yy);ctx.moveTo(px+19,yy+7);ctx.lineTo(px+27,yy+7);ctx.stroke()}
if(t===T.PATH){ctx.fillStyle='#b49b6a48';if(v>.5)ctx.fillRect(px+5,py+12,3,2);if(v>.8)ctx.fillRect(px+23,py+24,2,2)}
if(t===T.BRIDGE){ctx.fillStyle='#8c654d';ctx.fillRect(px+2,py+2,TILE-4,TILE-4);ctx.fillStyle='#d2aa70';ctx.fillRect(px+4,py+4,TILE-8,TILE-8);ctx.fillStyle='#9b7450';for(let q=7;q<29;q+=7)ctx.fillRect(px+q,py+4,2,TILE-8)}
if(t===T.TREE){ctx.fillStyle='#765d42';ctx.fillRect(px+13,py+18,7,13);ctx.fillStyle=v>.5?'#356347':'#3e704d';ctx.beginPath();ctx.moveTo(px+16,py-5);ctx.lineTo(px+1,py+19);ctx.lineTo(px+7,py+18);ctx.lineTo(px+2,py+25);ctx.lineTo(px+29,py+25);ctx.lineTo(px+24,py+18);ctx.lineTo(px+31,py+20);ctx.closePath();ctx.fill();ctx.fillStyle='#8bb1705c';ctx.fillRect(px+7,py+8,5,3)}
if(t===T.ROCK){ctx.fillStyle='#818d7c';ctx.beginPath();ctx.moveTo(px+5,py+26);ctx.lineTo(px+9,py+11);ctx.lineTo(px+18,py+5);ctx.lineTo(px+27,py+13);ctx.lineTo(px+28,py+26);ctx.fill();ctx.fillStyle='#b5bc9b';ctx.fillRect(px+12,py+12,5,2)} }
function drawBuilding(s,cx,cy){let x=s.x*TILE-cx,y=s.y*TILE-cy,w=s.w*TILE,h=s.h*TILE;ctx.fillStyle='#00000022';ctx.fillRect(x-4,y+h-1,w+8,8);ctx.fillStyle=s.wall;ctx.fillRect(x+4,y+12,w-8,h-12);ctx.fillStyle=s.roof;ctx.beginPath();ctx.moveTo(x-3,y+15);ctx.lineTo(x+w/2,y-9);ctx.lineTo(x+w+3,y+15);ctx.closePath();ctx.fill();ctx.fillStyle='#ffffff27';ctx.fillRect(x+8,y+12,w-20,3);ctx.fillStyle='#805b45';ctx.fillRect(x+w/2-7,y+h-21,14,21);ctx.fillStyle='#f3dfaa';ctx.fillRect(x+10,y+22,9,10);ctx.fillRect(x+w-19,y+22,9,10);ctx.fillStyle='#92aa94';ctx.fillRect(x+12,y+23,5,7);ctx.fillRect(x+w-17,y+23,5,7);ctx.fillStyle='#835e49';ctx.fillRect(x+w/2-2,y+h-10,2,2)}
function drawCharacter(x,y,emoji,name,playerCharacter=false,dir='down'){const px=x*TILE+TILE/2,py=y*TILE+TILE/2;ctx.fillStyle='#263c3035';ctx.beginPath();ctx.ellipse(px,py+9,11,5,0,0,Math.PI*2);ctx.fill();if(playerCharacter){ctx.fillStyle='#2e493d';ctx.fillRect(px-7,py-2,14,12);ctx.fillStyle='#d2aa78';ctx.fillRect(px-6,py-11,12,11);ctx.fillStyle='#526e57';ctx.fillRect(px-8,py-14,16,5);ctx.fillStyle='#e7e7c7';ctx.fillRect(px-3,py-6,2,2);ctx.fillRect(px+3,py-6,2,2);ctx.fillStyle='#684f44';if(dir==='left')ctx.fillRect(px-7,py-5,2,4);if(dir==='right')ctx.fillRect(px+5,py-5,2,4)}else{ctx.font='23px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(emoji,px,py-2)}if(!playerCharacter){ctx.fillStyle='#163a34c9';ctx.font='9px "DM Sans"';ctx.textAlign='center';ctx.textBaseline='alphabetic';let tw=ctx.measureText(name).width;ctx.fillStyle='#f7f4e8df';ctx.fillRect(px-tw/2-4,py-29,tw+8,13);ctx.fillStyle='#345449';ctx.fillText(name,px,py-19)}}
function drawWorld(){let camX=Math.max(0,Math.min(MW*TILE-canvas.width,player.x*TILE-canvas.width/2)),camY=Math.max(0,Math.min(MH*TILE-canvas.height,player.y*TILE-canvas.height/2));ctx.clearRect(0,0,canvas.width,canvas.height);let sx=Math.floor(camX/TILE),sy=Math.floor(camY/TILE),ex=Math.min(MW,sx+Math.ceil(canvas.width/TILE)+2),ey=Math.min(MH,sy+Math.ceil(canvas.height/TILE)+2);for(let y=sy;y<ey;y++)for(let x=sx;x<ex;x++)tileDraw(x,y,get(x,y),x-sx,y-sy);for(const s of structures)drawBuilding(s,camX,camY);for(const o of objects){if(Math.hypot(o.x-player.x,o.y-player.y)<20)drawCharacter(o.x,o.y,o.emoji,o.name)}drawCharacter(player.x,player.y,'',state.name||'Rowan',true,player.dir);let zone=zoneAt(player.x,player.y);document.getElementById('locationName').textContent=zone.name;document.getElementById('locationIcon').textContent=zone.icon;document.getElementById('locationSub').textContent=zone.sub;let mins=Math.floor(state.time/60),hh=9+Math.floor(mins/60),mm=mins%60;document.getElementById('worldLabel').textContent=zone.short+' · '+String(hh).padStart(2,'0')+':'+String(mm).padStart(2,'0')+' AM';requestAnimationFrame(drawWorld)}
function zoneAt(x,y){if(x<32&&y<27)return{name:'Whisperwood',icon:'🌲',sub:'THE VERDANT VALE · OLD-GROWTH FOREST',short:'WHISPERWOOD'};if(x>57&&y>34)return{name:'Stillwater Lake',icon:'🌊',sub:'THE VERDANT VALE · EASTERN SHORE',short:'STILLWATER'};if(x>44&&y>45)return{name:'Sunmeadow',icon:'🌼',sub:'THE VERDANT VALE · SOUTHERN MEADOW',short:'SUNMEADOW'};if(x>43&&y<29)return{name:'Windward Rise',icon:'⛰️',sub:'THE VERDANT VALE · NORTH TRAIL',short:'WINDWARD RISE'};if(x>27&&x<50&&y>25&&y<42)return{name:'Mossbell Village',icon:'🌱',sub:'THE VERDANT VALE · EASTERN REACH',short:'MOSSBELL'};return{name:'Fernway Meadow',icon:'🌾',sub:'THE VERDANT VALE · OPEN COUNTRY',short:'FERNWAY MEADOW'}}
function blocked(x,y){const t=get(Math.floor(x),Math.floor(y));if(t===T.TREE||t===T.WATER||t===T.ROCK)return true;for(const s of structures)if(x>=s.x-0.5&&x<s.x+s.w+0.5&&y>=s.y-0.7&&y<s.y+s.h+0.15)return true;return false}

