function blocked(x,y){const t=get(Math.floor(x),Math.floor(y));if(t===T.TREE||t===T.WATER||t===T.ROCK)return true;for(const s of structures)if(x>=s.x-0.5&&x<s.x+s.w+0.5&&y>=s.y-0.7&&y<s.y+s.h+0.15)return true;for(const o of objects)if(o.kind!=='lookout'&&Math.hypot(x-o.x,y-o.y)<.62)return true;return false}
function move(dx,dy){if(activeBattle||document.getElementById('dialogModal').classList.contains('open')||document.getElementById('mapModal').classList.contains('open'))return;let dir=dx<0?'left':dx>0?'right':dy<0?'up':'down';player.dir=dir;const nx=player.x+dx,ny=player.y+dy;if(!blocked(nx,ny)){player.x=nx;player.y=ny;state.time++;if(get(Math.floor(nx),Math.floor(ny))===T.TALL&&Math.random()<.14&&Date.now()-lastEncounter>9000){lastEncounter=Date.now();wildEncounter()}if(Date.now()-lastSave>8000)saveGame()}}
function nearestObject(){let options=objects.map(o=>({...o,d:Math.hypot(o.x-player.x,o.y-player.y)})).filter(o=>o.d<1.6).sort((a,b)=>a.d-b.d);return options[0]}
function interact(){if(activeBattle)return;const o=nearestObject();if(!o){let x=player.x+(player.dir==='left'?-1:player.dir==='right'?1:0),y=player.y+(player.dir==='up'?-1:player.dir==='down'?1:0);if(get(Math.floor(x),Math.floor(y))===T.TALL){wildEncounter(true);return}toast('The breeze carries a soft, leafy whisper.');return}if(o.kind==='elder')talkElder();else if(o.kind==='mira')talkMira();else if(o.kind==='board')talkBoard();else if(o.kind==='lookout')talkLookout()}
function openDialog(title,text,buttons){document.getElementById('dialogTitle').textContent=title;document.getElementById('dialogText').textContent=text;const actions=document.getElementById('dialogActions');actions.innerHTML='';for(const b of buttons){const el=document.createElement('button');el.className=b.secondary?'secondary-btn':'primary-btn';el.textContent=b.label;el.onclick=()=>{closeDialog();b.action?.()};actions.appendChild(el)}document.getElementById('dialogModal').classList.add('open')}
function closeDialog(){document.getElementById('dialogModal').classList.remove('open')}
function talkElder(){if(state.story===0){openDialog('Elder Fern','Ah, Rowan. The valley has been dreaming in colors again. I think it is ready to meet you. Choose a companion, and let the old trails show you the way.',[{label:'I’m ready',action:()=>{state.story=1;updateUI();saveGame();showStarter()}}]);return}if(state.story===1){showStarter();return}if(state.story===2){openDialog('Elder Fern','A little friend on the trail! The bonds we choose change the shape of the whole journey. Go on now—show me who you found.',[{label:'I’ll be back',secondary:true}]);return}if(state.story===3){state.story=4;state.shards+=3;state.notes++;updateUI();saveGame();openDialog('Elder Fern','You found a friend, and the reeds are singing your name. Take these three sun-shards. Follow the east trail to Stillwater Lake—the light there is older than Mossbell itself.',[{label:'Follow the light',action:()=>toast('New story chapter unlocked · Stillwater Lake')}]);return}if(state.story===4){openDialog('Elder Fern','The water remembers. At the eastern shore, you will find a clue in the reeds. Keep your eyes open, Trailkeeper.',[{label:'I will'}]);return}openDialog('Elder Fern','The Vale has a thousand paths, Rowan. Some are made by footsteps. Others appear only when you are ready.',[{label:'Thank you, Fern'}])}
function showStarter(){openDialog('A companion for the road','Three little lives are waiting in Fern’s garden. Every one of them has a story. Who will you walk beside?',species.slice(0,3).map((s,i)=>({label:s.emoji+' '+s.name,action:()=>{if(state.party.length===1&&state.party[0].species===0&&state.story===1)state.party[0]={species:i,level:3,hp:s.max,xp:0};else if(!state.party.some(p=>p.species===i)&&state.party.length<4)state.party.push({species:i,level:2,hp:s.max,xp:0});state.story=2;updateUI();saveGame();toast(s.name+' joined your journey!')}}))}
function talkMira(){if(state.story<4){openDialog('Mira, the wayfarer','The trails are old, but they never lead the same place twice. Try the tall grass beyond the village—something lovely always lives there.',[{label:'I’ll take a look'}]);return}openDialog('Mira, the wayfarer','I saw a strange glow by Stillwater last night. The little creatures have been gathering there. I think they know something we don’t.',[{label:'Thanks, Mira'}])}
function talkBoard(){state.notes++;updateUI();saveGame();openDialog('Mossbell Trail Board','FIELD NOTE #'+String(state.notes).padStart(2,'0')+'\n\nEast: Stillwater Lake, where the water holds the sky.\nNorth: Whisperwood, where even old trees have secrets.\nSouth: Sunmeadow, where the wildflowers never sleep.',[{label:'Close'}])}
function talkLookout(){if(state.story===4){state.story=5;state.shards+=5;state.notes++;updateUI();saveGame();openDialog('A glow in the reeds','A tiny sun-shard pulses beneath the water. As you reach for it, every creature at the lake turns to watch. The reflections shimmer—then settle. Something in the Vale has awakened, and it knows your name.',[{label:'Keep exploring',action:()=>toast('Chapter complete · The Vale is yours!')}]);return}openDialog('Stillwater Lake','Reeds sway at the water’s edge. In the ripples, the clouds look like distant mountains. A few old footprints lead back toward Mossbell.',[{label:'Listen to the water'}])}
function wildEncounter(forced=false){if(activeBattle||state.party.length===0)return;const base=get(Math.floor(player.x),Math.floor(player.y))===T.TALL?species.filter((_,i)=>[0,1,2,3].includes(i)):[species[2],species[4]];let pick=base[Math.floor(Math.random()*base.length)],index=species.indexOf(pick);if(Math.random()<.15)index=4;const s=spec(index),level=1+Math.floor(Math.random()*3),max=s.max+level*2;activeBattle={species:index,level,hp:max,max,forced,turn:0};battleBusy=false;renderBattle('A wild '+s.name+' is watching you carefully.');document.getElementById('battleModal').classList.add('open')}
function renderBattle(message){const b=activeBattle,p=companion(),s=spec(b.species),a=spec(p.species);document.getElementById('battleTitle').textContent='A wild '+s.name+' appeared!';document.getElementById('enemyName').textContent=s.name;document.getElementById('enemyLevel').textContent='LV '+b.level;document.getElementById('enemySprite').textContent=s.emoji;document.getElementById('enemyHp').style.width=Math.max(0,b.hp/b.max*100)+'%';document.getElementById('allyName').textContent=a.name;document.getElementById('allyLevel').textContent='LV '+p.level;document.getElementById('allySprite').textContent=a.emoji;document.getElementById('allyHp').style.width=Math.max(0,p.hp/a.max*100)+'%';document.getElementById('battleMessage').textContent=message;let acts=[{label:'✦  Quick strike',action:strike},{label:'🍓  Use berry ('+state.berries+')',action:useBerry},{label:'🔴  Trail capsule ('+state.capsules+')',action:capture,capture:true},{label:'↗  Leave',action:flee}];document.getElementById('battleActions').innerHTML='';acts.forEach((v,i)=>{let btn=document.createElement('button');btn.className='action-btn'+(v.capture?' capture':'');btn.textContent=v.label;btn.disabled=battleBusy||(i===2&&state.capsules<1)||(i===1&&(state.berries<1||companion().hp>=spec(companion().species).max));btn.onclick=v.action;document.getElementById('battleActions').append(btn)})}
function enemyTurn(message){if(!activeBattle)return;battleBusy=true;renderBattle(message);setTimeout(()=>{if(!activeBattle)return;const b=activeBattle,p=companion(),s=spec(b.species),dmg=Math.max(2,Math.floor(s.attack*.55+Math.random()*s.attack*.65-b.turn*.3));p.hp=Math.max(0,p.hp-dmg);b.turn++;if(p.hp<=0){p.hp=Math.max(1,Math.floor(spec(p.species).max*.45));state.berries=Math.max(0,state.berries-1);endBattle(s.name+' settled down. '+spec(p.species).name+' needs a rest.');return}battleBusy=false;updateUI();saveGame();renderBattle(s.name+' gave a playful little bump! Your companion lost '+dmg+' vigor.');},600)}
function strike(){if(!activeBattle||battleBusy)return;const b=activeBattle,p=companion(),a=spec(p.species),damage=Math.max(4,Math.floor(a.attack*(.75+Math.random()*.55)+p.level));b.hp=Math.max(0,b.hp-damage);if(b.hp<=0){state.shards+=1;battleBusy=true;renderBattle(a.name+' made a new friend! +1 sun-shard');setTimeout(()=>endBattle('You and '+a.name+' found a rhythm. +1 sun-shard.'),800);return}enemyTurn(a.name+' used Leaf Flick!')}
function useBerry(){if(!activeBattle||battleBusy||state.berries<1)return;state.berries--;const p=companion(),s=spec(p.species);p.hp=Math.min(s.max,p.hp+15);enemyTurn('A sweet berry restored '+p.name+' by 15 vigor.')}
function capture(){if(!activeBattle||battleBusy||state.capsules<1)return;state.capsules--;const b=activeBattle,s=spec(b.species),chance=.38+(1-b.hp/b.max)*.52;if(Math.random()<chance&&state.party.length<4){state.party.push({species:b.species,level:b.level,hp:s.max+2*b.level,xp:0});if(state.story===2)state.story=3;updateUI();battleBusy=true;renderBattle(s.name+' curled up in your trail capsule!');setTimeout(()=>endBattle(s.name+' joined your companions!'),850);return}enemyTurn('The capsule wobbled… then '+s.name+' popped back out!')}
function flee(){if(!activeBattle||battleBusy)return;if(activeBattle.forced){renderBattle('There’s no rush. Stay a little longer, or make a new friend.');return}if(Math.random()<.8)endBattle('You slipped away safely.');else enemyTurn('The wild one blocks your path!')}
function endBattle(message){document.getElementById('battleModal').classList.remove('open');activeBattle=null;battleBusy=false;updateUI();saveGame();toast(message)}
function drawMap(){const c=document.getElementById('minimap'),m=c.getContext('2d'),tw=c.width/MW,th=c.height/MH;m.clearRect(0,0,c.width,c.height);for(let y=0;y<MH;y++)for(let x=0;x<MW;x++){let t=get(x,y);m.fillStyle=t===T.WATER?'#77b6c0':t===T.TREE?'#426952':t===T.TALL?'#8fbd83':t===T.PATH||t===T.BRIDGE?'#d9c18e':t===T.FLOWER?'#96c486':'#70a87a';m.fillRect(x*tw,y*th,tw+.3,th+.3)}m.fillStyle='#daa975';m.fillRect(29*tw,26*th,21*tw,17*th);m.fillStyle='#ba7958';for(const s of structures)m.fillRect(s.x*tw,s.y*th,s.w*tw,s.h*th);m.fillStyle='#fff1a3';m.beginPath();m.arc(player.x*tw+tw/2,player.y*th+th/2,5,0,Math.PI*2);m.fill();m.strokeStyle='#5e5038';m.lineWidth=1.5;m.stroke()}
function keyDown(e){let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','w','a','s','d'].includes(k))e.preventDefault();if(k===' '||k==='enter'){if(!keys[k])interact();keys[k]=true;return}keys[k]=true}function keyUp(e){keys[e.key.toLowerCase()]=false}
window.addEventListener('keydown',keyDown);window.addEventListener('keyup',keyUp);window.addEventListener('blur',()=>keys={});function gameLoop(now){let dx=0,dy=0;if(now-lastMove>130){if(keys.arrowup||keys.w)dy=-1;else if(keys.arrowdown||keys.s)dy=1;else if(keys.arrowleft||keys.a)dx=-1;else if(keys.arrowright||keys.d)dx=1;if(dx||dy){move(dx,dy);lastMove=now}}requestAnimationFrame(gameLoop)}
document.querySelectorAll('.dpad button[data-dir]').forEach(btn=>{const dir=btn.dataset.dir;btn.addEventListener('pointerdown',e=>{e.preventDefault();keys[dir]=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>btn.addEventListener(ev,()=>keys[dir]=false))});function mobileLoop(now){if(now-lastMove>150){let dx=keys.left?-1:keys.right?1:0,dy=keys.up?-1:keys.down?1:0;if(dx||dy){move(dx,dy);lastMove=now}}requestAnimationFrame(mobileLoop)}document.getElementById('touchInteract').addEventListener('pointerdown',e=>{e.preventDefault();interact()});
document.getElementById('mapButton').onclick=()=>{drawMap();document.getElementById('mapModal').classList.add('open')};document.getElementById('mapClose').onclick=()=>document.getElementById('mapModal').classList.remove('open');document.getElementById('dialogClose').onclick=closeDialog;document.querySelectorAll('.modal-backdrop').forEach(el=>el.addEventListener('click',e=>{if(e.target===el)el.classList.remove('open')}));
function resize(){const rect=canvas.getBoundingClientRect();const dpr=Math.min(devicePixelRatio||1,2);const w=Math.max(1,Math.round(rect.width*dpr)),h=Math.max(1,Math.round(rect.height*dpr));if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;ctx.imageSmoothingEnabled=false}}new ResizeObserver(resize).observe(canvas);resize();requestAnimationFrame(drawWorld);requestAnimationFrame(gameLoop);requestAnimationFrame(mobileLoop);setInterval(()=>{if(Date.now()-lastSave>12000)saveGame()},5000);window.addEventListener('beforeunload',saveGame);
})();
